// console.log('sdsd', missingRequestIds);


const requestIdCounts = new Map();

// Iterate through the array and count occurrences
data1.forEach(item => {
    const requestId = item.requestId;
    if (requestIdCounts.has(requestId)) {
        requestIdCounts.set(requestId, requestIdCounts.get(requestId) + 1);
    } else {
        requestIdCounts.set(requestId, 1);
    }
});

// Filter requestIds that appear more than once
const duplicateRequestIds = [];
requestIdCounts.forEach((count, requestId) => {
    if (count > 1) {
        duplicateRequestIds.push(requestId);
    }
});

console.log("Duplicate requestIds:", duplicateRequestIds, data1.length);